  @override
  String categoriesCount(int count) {
    final int n = count.abs();
    final int m = n % 100;
    if (n == 0) return 'لا توجد فئات';
    if (n == 1) return 'فئة واحدة';
    if (n == 2) return 'فئتان';
    if (m >= 3 && m <= 10) return '${count} فئات';
    if (m >= 11) return '${count} فئة';
    return '${count} فئة';
  }

  @override
  String favoritesCount(int count) {
    final int n = count.abs();
    final int m = n % 100;
    if (n == 0) return 'لا توجد عناصر';
    if (n == 1) return 'عنصر واحد';
    if (n == 2) return 'عنصران';
    if (m >= 3 && m <= 10) return '${count} عناصر';
    if (m >= 11) return '${count} عنصرًا';
    return '${count} عنصر';
  }

  @override
  String itemsCount(int count) {
    final int n = count.abs();
    final int m = n % 100;
    if (n == 0) return 'لا توجد عناصر';
    if (n == 1) return 'عنصر واحد';
    if (n == 2) return 'عنصران';
    if (m >= 3 && m <= 10) return '${count} عناصر';
    if (m >= 11) return '${count} عنصرًا';
    return '${count} عنصر';
  }

